const lead = $input.first().json;
const roi = lead.roiCalculation || {};
const tier = lead.leadTier || 'unknown';
const tierEmoji = { hot: '🔥', warm: '☀️', cold: '🧊' }[tier] || '📊';

return [{
  json: {
    ...lead,
    tierEmoji,
    formattedROI: `$${Math.round(roi.annualValue || 0).toLocaleString()}`,
    formattedHours: `${Math.round(roi.hoursPerWeek || 0)} hrs/wk`,
  }
}];

